import React from "react";
import { LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid } from "recharts";

export default function TrafficChart({ alerts }) {
  // Build simple time‑bucketed data (last 5 minutes)
  const now = Date.now();
  const data = Array.from({ length: 5 }, (_, i) => {
    const minute = new Date(now - i * 60000);
    const count = alerts.filter(
      a => new Date(a.detected_at) > minute
    ).length;
    return {
      time: minute.toLocaleTimeString([], { minute: "2-digit" }),
      count,
    };
  }).reverse();

  return (
    <LineChart width={500} height={300} data={data}>
      <CartesianGrid strokeDasharray="3 3" />
      <XAxis dataKey="time" />
      <YAxis allowDecimals={false} />
      <Tooltip />
      <Line type="monotone" dataKey="count" stroke="#8884d8" strokeWidth={2} dot={false} />
    </LineChart>
  );
}
